insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_150'
from (values
('127.920.d.1.A',3,'A student in a transportation practicum learns the names of the tools and the safety rules of the shop where she is placed. She is:','["demonstrating the technical knowledge and skills related to her career pathway", "ignoring safety", "describing seats", "avoiding the shop"]'::jsonb,0,'Technical knowledge.','original'),
('127.920.d.1.A',4,'In a practicum, technical knowledge helps a student to:','["avoid supervisors", "perform workplace tasks correctly and safely", "skip training", "ignore rules"]'::jsonb,1,'Why it matters.','original'),
('127.920.d.1.B',3,'A student lists diesel technician, dispatcher and starting her own towing company as options after graduation. She is:','["ignoring careers", "describing tires", "identifying employment opportunities, including entrepreneurship opportunities", "describing seats"]'::jsonb,2,'Career options.','original'),
('127.920.d.1.B',4,'Opening a mobile repair business is an example of:','["a hobby only", "a classroom rule", "unemployment", "entrepreneurship"]'::jsonb,3,'Entrepreneur.','original'),
('127.920.d.1.C',3,'A student helps a crew finish a loading job by sharing tasks, listening to the lead and stepping up when someone is missing. She is:','["demonstrating principles of group participation, team concept and leadership", "avoiding the crew", "working alone", "ignoring the lead"]'::jsonb,0,'Group work.','original'),
('127.920.d.1.C',4,'An effective team leader usually:','["ignores others", "guides the group and shares credit", "avoids tasks", "takes all credit"]'::jsonb,1,'Leader.','original'),
('127.920.d.1.D',3,'A student finds a part number, asks a coworker for help and talks to a customer to solve a work order problem. She is:','["guessing", "avoiding people", "applying competencies related to resources, information, interpersonal skills and problem solving", "skipping steps"]'::jsonb,2,'Competencies.','original'),
('127.920.d.1.D',4,'Using a manual to look up a spec is an example of using:','["only memory", "only a hunch", "only luck", "information as a resource"]'::jsonb,3,'Information.','original'),
('127.920.d.1.E',3,'A student reads about industry certificates, such as a commercial driver''s license and welding credentials, that could help her get hired. She is:','["discussing certification opportunities", "describing tires", "describing seats", "ignoring credentials"]'::jsonb,0,'Certificates.','original'),
('127.920.d.1.E',4,'An industry certification shows an employer that a worker:','["lacks training", "has met a recognized skill standard", "paid a fine", "is hiding skills"]'::jsonb,1,'Certification value.','original'),
('127.920.d.1.F',3,'A student reviews where the fire extinguisher, the exit and the first-aid kit are and what to do if a hose bursts. She is:','["ignoring emergencies", "describing tires", "discussing response plans to emergency situations", "describing seats"]'::jsonb,2,'Emergency plans.','original'),
('127.920.d.1.F',4,'If an emergency plan is posted in the shop, workers should:','["learn it during the crisis", "ignore it", "hide it", "know the plan before an emergency happens"]'::jsonb,3,'Know it first.','original'),
('127.920.d.1.G',3,'A student shows up early, stays honest on her time sheet and finishes her tasks, which are what supervisors expect. She is:','["identifying employers'' expectations and appropriate work habits and ethical conduct", "describing seats", "ignoring expectations", "describing tires"]'::jsonb,0,'Employer expectations.','original'),
('127.920.d.1.G',4,'A reliable employee is one who:','["skips tasks", "arrives on time and follows through", "is often late", "hides errors"]'::jsonb,1,'Reliability.','original'),
('127.920.d.1.H',3,'A student writes a goal to earn her license in two years and lists the steps and classes needed. She is:','["describing tires", "avoiding goals", "developing personal goals, objectives and strategies as part of a plan for future career and educational planning", "describing seats"]'::jsonb,2,'Goal setting.','original'),
('127.920.d.1.H',4,'A strategy in a goal plan is:','["a delay", "a wish", "the goal itself", "the specific steps taken to reach the goal"]'::jsonb,3,'Strategy.','original'),
('127.920.d.2.A',3,'A student studies how electric trucks, GPS fleet tracking and driver-assist systems are changing the transportation industry. She is:','["extending knowledge of new and emerging transportation technologies", "ignoring technology", "describing tires", "describing seats"]'::jsonb,0,'New technology.','original'),
('127.920.d.2.A',4,'Fleet tracking systems help a trucking company to:','["hide routes", "monitor routes, fuel use and delivery times", "lose trucks", "avoid fuel"]'::jsonb,1,'Fleet tracking.','original'),
('127.920.d.2.B',3,'A student in a corequisite diesel course practices diagnosing a fault code with a scan tool at a higher skill level than before. She is:','["guessing", "skipping the tool", "demonstrating advanced technical skills related to the corequisite course", "avoiding the course"]'::jsonb,2,'Advanced skills.','original'),
('127.920.d.2.B',4,'Advanced technical skills are best built through:','["skipping labs", "only reading", "only watching", "hands-on practice with feedback"]'::jsonb,3,'Practice.','original'),
('127.920.d.2.C',3,'A student learns to use a diagnostic scanner, a torque multiplier and a lift safely on the job. She is:','["demonstrating an understanding of the use of advanced tools and equipment", "describing tires", "ignoring tools", "describing seats"]'::jsonb,0,'Advanced tools.','original'),
('127.920.d.2.C',4,'Before using advanced equipment, a worker should:','["skip steps", "be trained and follow the safety instructions", "ignore guards", "guess"]'::jsonb,1,'Train first.','original'),
('127.920.d.2.D',3,'A student reads how engineers test battery ranges and cleaner fuels to improve transportation. She is:','["describing seats", "ignoring research", "demonstrating an understanding of research and development in the transportation industry", "describing tires"]'::jsonb,2,'R and D.','original'),
('127.920.d.2.D',4,'Research and development in transportation aims to:','["slow vehicles", "add pollution", "raise costs only", "create safer, cleaner and more efficient vehicles"]'::jsonb,3,'R and D goal.','original'),
('127.920.d.3.A',3,'A student connects what she learned in her corequisite class about brakes to the work she does on a practicum vehicle. She is:','["demonstrating a deeper understanding of the corequisite course", "avoiding class", "guessing", "ignoring brakes"]'::jsonb,0,'Deeper understanding.','original'),
('127.920.d.3.A',4,'Practicum work deepens classroom learning because it lets students:','["forget content", "apply what they learned in a real setting", "skip class", "avoid work"]'::jsonb,1,'Apply learning.','original'),
('127.920.d.3.B',3,'A student repeats a wheel-bearing service under supervision until her work meets the shop''s standard. She is:','["guessing", "skipping checks", "developing hands-on skills at an industry-accepted standard", "rushing"]'::jsonb,2,'Hands-on standard.','original'),
('127.920.d.3.B',4,'An industry-accepted standard means the work:','["is fast only", "is cheap only", "is personal style", "meets what employers across the field expect"]'::jsonb,3,'Industry standard.','original'),
('127.920.d.3.C',3,'A student logs her hours and skill checks toward a certificate that employers recognize. She is:','["exhibiting progress toward achieving industry-recognized documentation of specific skills", "hiding progress", "guessing", "ignoring records"]'::jsonb,0,'Documented progress.','original'),
('127.920.d.3.C',4,'Industry-recognized documentation of skills can help a student:','["avoid jobs", "show employers proof of her abilities", "hide skills", "lose hours"]'::jsonb,1,'Proof of skill.','original'),
('127.921.d.1.A',3,'A new trainee reads the company handbook and follows the check-in steps and break rules exactly. She is:','["ignoring rules", "breaking policy", "adhering to policies and procedures", "guessing steps"]'::jsonb,2,'Policies.','original'),
('127.921.d.1.A',4,'Workplace policies exist mostly to:','["limit workers", "reduce pay", "add confusion", "keep operations fair, safe and consistent"]'::jsonb,3,'Why policies.','original'),
('127.921.d.1.B',3,'A trainee arrives ten minutes early, is dependable and keeps a positive attitude through a long shift. She is:','["demonstrating positive work attitudes and behaviors, including punctuality", "avoiding tasks", "complaining", "being late"]'::jsonb,0,'Positive attitude.','original'),
('127.921.d.1.B',4,'Punctuality at work shows that a person:','["is unreliable", "respects the team''s time", "dislikes the job", "is careless"]'::jsonb,1,'Punctual.','original'),
('127.921.d.1.C',3,'A supervisor tells a trainee that her weld spacing was uneven, and she thanks him and fixes it. She is:','["blaming others", "ignoring feedback", "accepting constructive criticism", "arguing back"]'::jsonb,2,'Feedback.','original'),
('127.921.d.1.C',4,'The best use of constructive criticism is to:','["ignore it", "get angry", "quit", "learn from it and improve"]'::jsonb,3,'Improve.','original'),
('127.921.d.1.D',3,'A trainee is offered a chance to sign off a time card for a coworker who left early, and she thinks it through and refuses. She is:','["applying ethical reasoning to make an ethical decision", "guessing", "breaking the rule", "hiding the truth"]'::jsonb,0,'Ethical decision.','original'),
('127.921.d.1.D',4,'Signing a time card for work someone did not do is:','["helpful", "dishonest", "routine", "permitted"]'::jsonb,1,'Time card fraud.','original'),
('127.921.d.1.E',3,'A trainee double-checks each bolt on a delivered cart and redoes a weak joint before handing it over. She is:','["rushing", "accepting poor work", "completing tasks with the highest standards to ensure quality products and services", "skipping checks"]'::jsonb,2,'Quality.','original'),
('127.921.d.1.E',4,'Quality work matters because customers rely on:','["quick shortcuts", "hidden defects", "low prices only", "products and services that are done right"]'::jsonb,3,'Customer trust.','original'),
('127.921.d.1.F',3,'A trainee wears a clean uniform, ties her hair back and wears her steel-toe boots on the first day. She is:','["modeling professional appearance, including appropriate dress and grooming", "skipping boots", "ignoring dress", "dressing carelessly"]'::jsonb,0,'Appearance.','original'),
('127.921.d.1.F',4,'A professional appearance at work helps a person to:','["hide skill", "make a good impression and stay safe", "be unsafe", "draw complaints"]'::jsonb,1,'First impression.','original'),
('127.921.d.1.G',3,'A trainee puts on goggles, checks the guard on a saw and reports a frayed cord before turning anything on. She is:','["hiding hazards", "ignoring rules", "complying with safety rules and regulations to maintain safe and healthy working conditions", "skipping goggles"]'::jsonb,2,'Safety.','original'),
('127.921.d.1.G',4,'Reporting a frayed cord promptly is important because it:','["wastes time", "hides problems", "adds work", "prevents injury to others"]'::jsonb,3,'Report hazards.','original'),
('127.921.d.2.A',3,'A crew''s delivery van keeps overheating, and a trainee lists possible causes and a creative fix, like adding a cooling shroud. She is:','["analyzing elements of a problem to develop creative and innovative solutions", "guessing", "quitting", "ignoring the problem"]'::jsonb,0,'Creative solving.','original'),
('127.921.d.2.A',4,'A forklift keeps stalling at the dock. Why would a technician list each possible cause separately before testing anything?','["It makes the problem bigger", "Smaller pieces are easier to test and rule out one at a time", "It guarantees the first guess is right", "It avoids any testing"]'::jsonb,1,'Split a problem to find the real cause.','original'),
('127.921.d.2.B',3,'A trainee reads three online fixes for a rattling exhaust and decides which one matches the vehicle''s model and symptom. She is:','["ignoring all", "guessing", "critically analyzing information to determine its relevance to the problem-solving process", "copying blindly"]'::jsonb,2,'Relevance.','original'),
('127.921.d.2.B',4,'Information is most useful for solving a problem when it is:','["old and vague", "unrelated", "unverified", "relevant and accurate"]'::jsonb,3,'Relevant.','original'),
('127.921.d.2.C',3,'A trainee weighs repair, replace and rebuild options by cost, time and risk before choosing one. She is:','["comparing and contrasting alternatives using problem-solving and critical-thinking skills", "ignoring options", "picking at random", "guessing"]'::jsonb,0,'Compare options.','original'),
('127.921.d.2.C',4,'Comparing alternatives before a decision helps you to:','["pick the first idea", "choose the best fit for the situation", "ignore costs", "avoid choosing"]'::jsonb,1,'Compare.','original'),
('127.921.d.2.D',3,'A trainee reads the service manual, checks a parts database and asks the supplier before ordering a replacement. She is:','["guessing", "skipping research", "conducting technical research to gather information necessary for decision making", "ordering blindly"]'::jsonb,2,'Technical research.','original'),
('127.921.d.2.D',4,'Good technical research relies on:','["random posts", "rumors", "guesses", "reliable sources such as manuals and manufacturer data"]'::jsonb,3,'Reliable sources.','original'),
('127.921.d.3.A',3,'A student studies what makes a leader trustworthy, positive, and willing to listen. She is:','["analyzing leadership characteristics related to trusting others and maintaining a positive attitude", "describing tires", "ignoring leaders", "describing seats"]'::jsonb,0,'Leadership traits.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_150'
from (values
('127.921.d.3.A',4,'A trait of a strong leader is that they:','["hide goals", "trust and encourage their team", "micromanage everything", "blame others"]'::jsonb,1,'Leader traits.','original'),
('127.921.d.3.B',3,'A trainee splits a long repair job with two others, each taking a section so that the whole job is done on time. She is:','["avoiding the team", "working alone", "demonstrating teamwork skills through working cooperatively with others to achieve goals", "competing"]'::jsonb,2,'Teamwork.','original'),
('127.921.d.3.B',4,'Cooperating on a shared goal usually means:','["one person does it all", "no one talks", "everyone waits", "each person contributes toward the result"]'::jsonb,3,'Cooperate.','original'),
('127.921.d.3.C',3,'A team meeting ends with everyone agreeing on a plan and later reviewing how to do better next time. They are:','["demonstrating teamwork processes that promote team building, consensus and continuous improvement", "dropping the plan", "avoiding meetings", "arguing"]'::jsonb,0,'Team process.','original'),
('127.921.d.3.C',4,'Consensus on a team means:','["one person decides", "members come to a decision they can all support", "a coin flip", "no decision"]'::jsonb,1,'Consensus.','original'),
('127.921.d.3.D',3,'A trainee finishes her part of a group project and also checks that the group''s part is complete before submitting. She is:','["blaming others", "ignoring the group", "demonstrating responsibility for group and individual work tasks", "avoiding tasks"]'::jsonb,2,'Responsibility.','original'),
('127.921.d.3.D',4,'Being responsible for a group task means:','["skipping it", "hiding mistakes", "leaving it to others", "owning your part and following it through"]'::jsonb,3,'Own it.','original'),
('127.921.d.3.E',3,'A trainee greets coworkers, keeps promises and helps a new hire so that people trust her. She is:','["establishing and maintaining effective working relationships in order to accomplish objectives", "avoiding coworkers", "ignoring others", "creating conflict"]'::jsonb,0,'Relationships.','original'),
('127.921.d.3.E',4,'Trust between coworkers grows when people:','["hide information", "keep their word", "break promises", "gossip"]'::jsonb,1,'Build trust.','original'),
('127.921.d.3.F',3,'A trainee calmly explains a scheduling concern to a coworker and listens to the reply. She is:','["ignoring the coworker", "yelling", "demonstrating effective working relationships using interpersonal skills", "avoiding talk"]'::jsonb,2,'Interpersonal.','original'),
('127.921.d.3.F',4,'Staying calm when you disagree helps you to:','["avoid facts", "win by force", "escalate", "keep the conversation productive"]'::jsonb,3,'Calm talk.','original'),
('127.921.d.3.G',3,'A trainee shares tools, thanks a helper and offers to cover a break so that the crew works smoothly. She is:','["using positive interpersonal skills to work cooperatively with others", "complaining", "hoarding tools", "ignoring helpers"]'::jsonb,0,'Positive skills.','original'),
('127.921.d.3.G',4,'A positive interpersonal habit at work is to:','["hoard tools", "say thank you and offer help", "gossip", "avoid greetings"]'::jsonb,1,'Positive habit.','original'),
('127.921.d.3.H',3,'Two trainees want different shifts, and they talk it through and trade so that both get something they need. They are:','["giving up", "refusing to talk", "negotiating effectively to arrive at decisions", "fighting"]'::jsonb,2,'Negotiation.','original'),
('127.921.d.3.H',4,'A good negotiation usually ends with:','["an argument", "no agreement", "a winner and a loser", "an agreement that works for both sides"]'::jsonb,3,'Win-win.','original'),
('127.921.d.3.I',3,'A trainee learns to greet a coworker in her language and respects their holiday leave. She is:','["demonstrating respect for individuals, including those from different cultures, genders and religions", "excluding people", "ignoring coworkers", "mocking others"]'::jsonb,0,'Respect.','original'),
('127.921.d.3.I',4,'Showing respect to coworkers from different backgrounds helps the workplace by:','["hurting morale", "building trust and cooperation", "creating tension", "reducing teamwork"]'::jsonb,1,'Respect value.','original'),
('127.921.d.3.J',3,'A team lead asks everyone''s ideas, including from newer and quieter members, and values each. She is:','["showing bias", "excluding members", "demonstrating sensitivity to and value for diversity", "ignoring ideas"]'::jsonb,2,'Diversity.','original'),
('127.921.d.3.J',4,'A team with diverse viewpoints can often:','["avoid ideas", "agree on everything", "solve fewer problems", "solve problems more creatively"]'::jsonb,3,'Diverse teams.','original'),
('127.921.d.4.A',3,'A trainee uses the right terms, like ''torque'' and ''tolerance'', when she explains a repair to a customer. She is:','["demonstrating the use of content, technical concepts and vocabulary when analyzing information", "guessing words", "avoiding terms", "using slang"]'::jsonb,0,'Technical vocab.','original'),
('127.921.d.4.A',4,'Using correct technical vocabulary at work helps people to:','["slow tasks", "communicate clearly and avoid mistakes", "hide meaning", "confuse others"]'::jsonb,1,'Clear terms.','original'),
('127.921.d.4.B',3,'A trainee asks a customer focused questions about a noise and then explains the findings in plain words. She is:','["avoiding customers", "guessing", "employing verbal skills when obtaining and conveying information", "mumbling"]'::jsonb,2,'Verbal skills.','original'),
('127.921.d.4.B',4,'Good verbal communication includes:','["mumbling", "talking over others", "avoiding eye contact", "speaking clearly and checking understanding"]'::jsonb,3,'Clear speech.','original'),
('127.921.d.4.C',3,'A trainee reads a manufacturer''s technical bulletin and a trade website to review a repair method. She is:','["using informational texts, Internet websites and technical materials to review and implement a procedure", "guessing", "ignoring texts", "skipping reading"]'::jsonb,0,'Technical reading.','original'),
('127.921.d.4.C',4,'Before using a procedure found online, a worker should:','["copy it fast", "confirm it with an approved source", "trust it blindly", "skip it"]'::jsonb,1,'Verify.','original'),
('127.921.d.4.D',3,'A trainee checks who wrote an article, when it was written and whether the manufacturer supports its claims. She is:','["trusting any source", "guessing", "evaluating the reliability of information from informational texts, Internet websites and technical materials", "ignoring dates"]'::jsonb,2,'Reliability.','original'),
('127.921.d.4.D',4,'A reliable source is usually:','["outdated", "unsourced", "anonymous", "current, credible and well supported"]'::jsonb,3,'Credible.','original'),
('127.921.d.4.E',3,'A trainee notices her supervisor''s crossed arms and tight tone and asks if she should adjust her plan. She is:','["interpreting verbal and nonverbal cues or behaviors to enhance communication", "ignoring cues", "avoiding people", "guessing"]'::jsonb,0,'Nonverbal.','original'),
('127.921.d.4.E',4,'Nonverbal cues, such as posture and facial expression, can:','["mean nothing", "signal feelings that words do not", "always be ignored", "replace all words"]'::jsonb,1,'Cues.','original'),
('127.921.d.4.F',3,'A trainee nods, takes notes and asks a follow-up question when a mentor explains a new process. She is:','["texting", "ignoring the mentor", "applying active listening skills to obtain and clarify information", "interrupting"]'::jsonb,2,'Active listening.','original'),
('127.921.d.4.F',4,'A mentor finishes explaining a torque sequence. Which reply shows active listening?','["\"Yeah, got it.\" while looking at a phone", "\"Can we talk about lunch?\"", "\"I already knew all that.\"", "\"So I tighten the center bolts first, then work outward, right?\""]'::jsonb,3,'Restating confirms understanding.','original'),
('127.921.d.4.G',3,'A trainee uses her math and writing skills to write a clear estimate and explain the costs to a client. She is:','["using academic skills to facilitate effective written and oral communication", "guessing", "skipping math", "avoiding writing"]'::jsonb,0,'Academic skills.','original'),
('127.921.d.4.G',4,'Strong writing skills help workers produce:','["more errors", "clear reports and instructions", "longer delays", "confusing notes"]'::jsonb,1,'Writing.','original'),
('127.921.d.5.A',3,'A trainee in her capstone placement studies the tasks of her chosen field in more depth and practices them under supervision. She is:','["avoiding practice", "changing fields daily", "developing advanced technical knowledge and skills related to the student''s personal career goal", "ignoring goals"]'::jsonb,2,'Advanced skills.','original'),
('127.921.d.5.A',4,'Advanced skills usually build on:','["no prior learning", "luck", "guesswork", "a strong base of earlier learning"]'::jsonb,3,'Build on basics.','original'),
('127.921.d.5.B',3,'A trainee completes a skills checklist with her supervisor to see which tasks she does well and which need practice. She is:','["evaluating technical skill proficiencies", "guessing", "hiding gaps", "ignoring skills"]'::jsonb,0,'Skill evaluation.','original'),
('127.921.d.5.B',4,'A skills evaluation is useful because it shows:','["only praise", "where to improve next", "only faults", "nothing"]'::jsonb,1,'Next steps.','original'),
('127.921.d.5.C',3,'A trainee listens carefully to her supervisor''s notes on her mistakes and asks how to fix them. She is:','["arguing", "ignoring notes", "accepting critical feedback provided by the supervisor", "blaming tools"]'::jsonb,2,'Take feedback.','original'),
('127.921.d.5.C',4,'A trainee who welcomes critical feedback is more likely to:','["be ignored", "stay the same", "lose skills", "grow and advance in the job"]'::jsonb,3,'Growth.','original'),
('127.921.d.6.B',3,'A trainee shows her portfolio of work samples and resume to a panel of local employers at a showcase. She is:','["presenting the portfolio to interested stakeholders", "avoiding the panel", "skipping the event", "hiding her work"]'::jsonb,0,'Present portfolio.','original'),
('127.921.d.6.B',4,'Presenting a portfolio to stakeholders gives a student a chance to:','["avoid feedback", "show her skills and make connections", "lose contacts", "hide skills"]'::jsonb,1,'Showcase.','original'),
('127.921.d.6.A.i',3,'A trainee adds the certificates and skill competencies she has earned to her professional portfolio. She is:','["guessing", "leaving it blank", "updating a professional portfolio to include attainment of technical skill competencies", "deleting records"]'::jsonb,2,'Add skills.','original'),
('127.921.d.6.A.i',4,'Documenting attained skills in a portfolio helps show:','["hidden grades", "what she cannot do", "nothing", "what a student can do"]'::jsonb,3,'Show skills.','original'),
('127.921.d.6.A.ii',3,'A trainee adds a summary of her job-shadow days and field trips to her portfolio. She is:','["updating a professional portfolio to include extended learning experiences", "guessing", "leaving it blank", "deleting records"]'::jsonb,0,'Add experiences.','original'),
('127.921.d.6.A.ii',4,'An example of an extended learning experience is:','["a nap", "a job shadow or internship", "a lunch break", "a seat change"]'::jsonb,1,'Extended learning.','original'),
('127.921.d.6.A.iii',3,'A trainee writes a short abstract of the technical knowledge she gained and puts it in her portfolio. She is:','["deleting records", "leaving it blank", "updating a professional portfolio to include an abstract of technical knowledge", "guessing"]'::jsonb,2,'Abstract.','original'),
('127.921.d.6.A.iii',4,'An abstract in a portfolio is:','["a photo", "a full book", "a price list", "a brief summary of what was learned"]'::jsonb,3,'Abstract def.','original'),
('127.921.d.6.A.iv',3,'A trainee updates her resume with her new skills and places it in her portfolio. She is:','["updating a professional portfolio to include a resume", "leaving it blank", "deleting records", "guessing"]'::jsonb,0,'Add resume.','original'),
('127.921.d.6.A.iv',4,'A resume in a portfolio should be:','["outdated", "current, accurate and well organized", "messy", "exaggerated"]'::jsonb,1,'Good resume.','original'),
('127.921.d.6.A.v',3,'A trainee photographs a finished weld joint and a repaired part and adds them to her portfolio. She is:','["guessing", "leaving it blank", "updating a professional portfolio to include samples of work", "deleting records"]'::jsonb,2,'Work samples.','original'),
